# region: digest
def digest(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
            return out
    return out

# region: fold
def fold(xs, offset=1):
    return [v + offset for v in xs]

# region: sift
def sift(xs, factor=3):
    return [v * factor for v in xs]

# region: render
def render(xs, limit=5):
    return [v if v <= limit else limit for v in xs]

# region: shape
def shape(xs):
    return {'n': len(xs), 'min': min(xs) if xs else 0, 'span': (max(xs) - min(xs)) if xs else 0}

# region: emit
def emit(summary, bar=4):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return emit(shape(render(sift(fold(digest(raw))))))

